<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import MiriCogItemPicker from '@/Components/MiriCogItemPicker.vue';
import { reactive } from 'vue';
const props = defineProps({ movementTypes: Array });
const selections = reactive(new Map());
let nextKey = 1;
const form = useForm({ movement_type: props.movementTypes[0], document_date: new Date().toLocaleDateString('en-CA'), from_location: '', to_location: '', receiver_name: '', receiver_email: '', issued_by_name: '', remarks: '', items: [{ row_key: nextKey++, item_type: 'Major equipment', item_id: '', quantity: 1, remarks: '' }] });
const addItem = () => form.items.push({ row_key: nextKey++, item_type: 'Major equipment', item_id: '', quantity: 1, remarks: '' });
const removeItem = (index) => form.items.length > 1 && form.items.splice(index, 1);
const selected = (line) => selections.get(line.row_key);
const submit = () => form.post(route('miri-cogs.store'));
</script>
<template><Head title="Create Miri COG"/><AuthenticatedLayout><section class="space-y-6"><header class="rounded-[2rem] border border-[#d8e7d4] bg-white p-7 shadow-sm"><p class="text-xs font-bold uppercase tracking-[.25em] text-[#4f9f4a]">Miri Inventory</p><h1 class="mt-2 text-3xl font-bold text-[#234222]">Create digital COG</h1><p class="mt-2 text-sm text-[#60745d]">Prepare a Dayang-branded movement document for one or more Miri items.</p></header><form class="space-y-6" @submit.prevent="submit"><section class="rounded-[2rem] border border-[#d8e7d4] bg-white p-6 shadow-sm"><h2 class="text-lg font-bold text-[#234222]">Movement details</h2><div class="mt-5 grid gap-4 md:grid-cols-2 lg:grid-cols-3"><label><span class="label-text">Movement type</span><select v-model="form.movement_type" class="input input-bordered mt-2 w-full"><option v-for="type in movementTypes" :key="type">{{ type }}</option></select></label><label><span class="label-text">Document date</span><input v-model="form.document_date" type="date" class="input input-bordered mt-2 w-full"/></label><label><span class="label-text">Issued by *</span><input v-model="form.issued_by_name" class="input input-bordered mt-2 w-full" placeholder="Staff name"/></label><label><span class="label-text">From location</span><input v-model="form.from_location" class="input input-bordered mt-2 w-full" placeholder="Miri base / yard"/></label><label><span class="label-text">To location</span><input v-model="form.to_location" class="input input-bordered mt-2 w-full" placeholder="Destination"/></label><label><span class="label-text">Receiver name</span><input v-model="form.receiver_name" class="input input-bordered mt-2 w-full" placeholder="Receiving staff"/></label><label><span class="label-text">Receiver email</span><input v-model="form.receiver_email" type="email" class="input input-bordered mt-2 w-full" placeholder="Optional"/></label><label class="md:col-span-2"><span class="label-text">Remarks</span><textarea v-model="form.remarks" class="textarea textarea-bordered mt-2 w-full" rows="2"/></label></div></section><section class="rounded-[2rem] border border-[#d8e7d4] bg-white p-6 shadow-sm"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-lg font-bold text-[#234222]">COG items</h2><p class="mt-1 text-sm text-slate-500">Item details are captured into the document when saved.</p></div><button type="button" class="rounded-xl bg-[#4f9f4a] px-4 py-2 text-sm font-bold text-white" @click="addItem">+ Add item</button></div><div v-for="(line, index) in form.items" :key="line.row_key" class="mt-4 grid gap-3 rounded-2xl border border-[#e1efdc] p-4 md:grid-cols-12"><label class="md:col-span-2"><span class="label-text">Type</span><select v-model="line.item_type" class="input input-bordered mt-2 w-full"><option>Major equipment</option><option>Rental</option></select></label><label class="md:col-span-4"><span class="label-text">Inventory item</span><MiriCogItemPicker v-model="line.item_id" :type="line.item_type" @selected="selections.set(line.row_key, $event)" /></label><div class="md:col-span-3 rounded-xl bg-[#f7fbf5] p-3 text-xs text-slate-600"><strong class="block text-[#234222]">Current location</strong>{{ selected(line)?.location || 'Select an item' }}</div><label class="md:col-span-1"><span class="label-text">Qty</span><input v-model="line.quantity" type="number" min="0.01" step="0.01" class="input input-bordered mt-2 w-full"/></label><button type="button" class="self-end rounded-xl border border-red-200 px-3 py-2 text-sm font-bold text-red-600 md:col-span-2" @click="removeItem(index)">Remove</button><input v-model="line.remarks" class="input input-bordered md:col-span-12" placeholder="Item remarks (optional)"/></div></section><div class="flex gap-3"><button type="submit" class="rounded-xl bg-[#234222] px-5 py-3 text-sm font-bold text-white" :disabled="form.processing">Create COG</button><Link class="btn" :href="route('miri-cogs.index')">Cancel</Link></div></form></section></AuthenticatedLayout></template>
